import { AnimatePresence, motion } from 'framer-motion';
import { ArrowLeft, ArrowRight, BookOpen, Check, ChevronDown, ChevronRight, Copy, ExternalLink, Github, Menu, ShieldCheck, X } from 'lucide-react';
import { useEffect, useState } from 'react';
import {
  auditEvents, controls, credibility, executionBoundaries, intentTypes, pipeline, principles,
  runtimeStates, users, x402Tracks,
} from './content';

const github = 'https://github.com/atonima-labs';
const docs = 'https://docs.atonima.com';
const sdkPackage = 'https://www.npmjs.com/package/@atonima/sdk';
const reveal = { initial: { opacity: 0, y: 20 }, whileInView: { opacity: 1, y: 0 }, viewport: { once: true, amount: .18 }, transition: { duration: .5 } };
const nav = [['Platform', '/#platform'], ['Architecture', '/#architecture'], ['Developers', '/#developers']];
const products = [
  { name: 'x402', href: '/x402', description: 'Agent-native payments and discovery' },
  { name: 'API + Runtime SDK', href: '/runtime', description: 'Semantic actions and automations' },
  { name: 'Discovery + Skills', href: '/discovery', description: 'Protocol intelligence for agents' },
  { name: 'Intent Infrastructure', href: '/intents', description: 'Validation, policy and compilation' },
];

export default function App() {
  const [menu, setMenu] = useState(false);
  const path = window.location.pathname.replace(/\/+$/, '') || '/';
  useEffect(() => { window.scrollTo(0, 0); }, [path]);
  return <div className="min-h-screen bg-ink text-white">
    <nav className="nav"><div className="shell flex h-[72px] items-center justify-between">
      <a href="/" className="flex items-center gap-3" aria-label="Atonima home"><Mark/><span className="font-semibold tracking-[-.02em]">atonima</span><span className="hidden rounded border border-white/10 px-2 py-1 font-mono text-[9px] uppercase tracking-[.15em] text-steel sm:inline">financial intent infrastructure</span></a>
      <div className="hidden items-center gap-7 lg:flex"><ProductMenu/>{nav.map(([label, href]) => <a key={label} className="nav-link" href={href}>{label}</a>)}</div>
      <div className="hidden items-center gap-3 lg:flex"><a href={github} target="_blank" rel="noreferrer" className="icon-button" aria-label="Atonima on GitHub"><Github className="size-4"/></a><a href="/build" className="button button-small">Build with Atonima <ArrowRight className="size-3.5"/></a></div>
      <button className="icon-button lg:hidden" onClick={() => setMenu(v => !v)} aria-label="Toggle navigation" aria-expanded={menu}>{menu ? <X className="size-5"/> : <Menu className="size-5"/>}</button>
    </div><AnimatePresence>{menu && <motion.div initial={{height:0, opacity:0}} animate={{height:'auto', opacity:1}} exit={{height:0, opacity:0}} className="overflow-hidden border-t border-white/10 bg-ink lg:hidden"><div className="shell py-4"><p className="py-2 font-mono text-[9px] uppercase tracking-wider text-steel">Products</p>{products.map(p=><a key={p.name} href={p.href} className="block py-2 text-sm text-cloud" onClick={() => setMenu(false)}>{p.name}</a>)}<div className="my-2 h-px bg-white/10"/>{nav.map(([label, href]) => <a key={label} href={href} className="block py-2 text-sm text-cloud" onClick={() => setMenu(false)}>{label}</a>)}<a href="/build" className="button mt-4 w-full" onClick={() => setMenu(false)}>Build with Atonima</a></div></motion.div>}</AnimatePresence></nav>

    <main>{path === '/' ? <>
      <Hero/>
      <TrustStrip/>
      <Platform/>
      <Architecture/>
      <IntentDemo/>
      <DiscoveryPreview/>
      <X402/>
      <Principles/>
      <Audience/>
      <Vision/>
      <CTA/>
    </> : path === '/x402' ? <X402Page/> : path === '/runtime' ? <RuntimePage/> : path === '/discovery' ? <DiscoveryPage/> : path === '/intents' ? <IntentsPage/> : path === '/build' ? <BuildPage/> : <NotFound/>}</main>
    <Footer/>
  </div>;
}

function ProductMenu(){return <div className="product-menu relative"><button className="nav-link flex items-center gap-1.5 py-6" aria-haspopup="true">Products <ChevronDown className="size-3"/></button><div className="product-popover">{products.map(p=><a key={p.name} href={p.href}><b>{p.name}</b><span>{p.description}</span></a>)}</div></div>}

function Mark({dark=false}:{dark?:boolean}) { return <span className={`mark ${dark ? 'mark-dark' : ''}`}><span/><i/></span>; }

function usePageMeta(title:string, description:string){useEffect(()=>{document.title=title;const selectors=['meta[name="description"]','meta[property="og:description"]','meta[name="twitter:description"]'];selectors.forEach(s=>document.querySelector(s)?.setAttribute('content',description));['meta[property="og:title"]','meta[name="twitter:title"]'].forEach(s=>document.querySelector(s)?.setAttribute('content',title));document.querySelector('link[rel="canonical"]')?.setAttribute('href',`${window.location.origin}${window.location.pathname}`);return()=>{document.title='Atonima | Financial Intent Infrastructure'}},[title,description])}

function ProductHero({tag,title,text,status}:{tag:string;title:string;text:string;status?:string}){return <section className="product-hero hero-grid pt-[72px]"><div className="shell py-24 sm:py-32"><a href="/" className="mb-10 inline-flex items-center gap-2 text-xs text-steel hover:text-white"><ArrowLeft className="size-3.5"/> Back to platform</a><motion.div initial={{opacity:0,y:18}} animate={{opacity:1,y:0}}><span className="eyebrow">{tag}</span>{status&&<span className="mb-5 inline-flex rounded-full border border-signal/25 bg-signal/10 px-3 py-1 font-mono text-[9px] uppercase tracking-wider text-signal">{status}</span>}<h1 className="max-w-5xl text-5xl font-semibold leading-[.98] tracking-[-.05em] sm:text-6xl lg:text-7xl">{title}</h1><p className="mt-7 max-w-2xl text-lg leading-8 text-cloud">{text}</p></motion.div></div></section>}

function X402Page(){usePageMeta('x402 | Atonima','A production-ready x402 facilitator and Bazaar discovery layer for agent-paid services on Stellar.');const specs=[
  ['Facilitator','Standard verify, settle and supported endpoints on testnet and pubnet, built on the Apache-2.0 @x402/stellar package.'],
  ['Strict authorization','Validate Soroban auth entries against the exact call, asset, amount and recipient; reject replay, expiry and tampering.'],
  ['Asset support','Support SEP-41 assets with USDC defaults, seven-decimal amount handling, classic keypairs and custom __check_auth accounts.'],
  ['Non-custodial fees','Sponsor network fees so buyers only need the payment asset. The facilitator never takes custody or becomes the source of funds.'],
  ['Self-hosting','Ship hosted and self-facilitated paths under a permissive OSI-approved license with configurable pricing, auth and rate limits.'],
  ['Wire conformance','Accept canonical v2 payloads unchanged, expose areFeesSponsored, return non-null rejection reasons and test both networks end to end.'],
];const discovery=[
  ['Catalog browsing','GET /discovery/resources with pagination and type, payTo, network, extensions, limit and offset filters.'],
  ['Natural-language search','GET /discovery/search with ranked retrieval, cursor pagination, partialResults and an evaluation plan for search quality.'],
  ['Automatic cataloging','Validate and index discovery metadata from PaymentPayload without requiring a separate seller registration step.'],
  ['HTTP + MCP resources','Treat MCP tools as first-class resources and key them using the resource URL and tool name tuple.'],
  ['Catalog integrity','Soft-drop invalid metadata, defend routeTemplate traversal after percent-decoding and report outcomes through EXTENSION-RESPONSES.'],
  ['Ecosystem compatibility','Track the evolving discovery conventions so Stellar resources remain interoperable with the wider x402 Bazaar ecosystem.'],
];return <><ProductHero tag="Product / x402" status="Product specification" title="Discover, authorize and pay for services—agent to agent." text="Atonima x402 brings payment facilitation and service discovery to agent commerce on Stellar, designed around the current x402 v2 wire format, Soroban authorization and open ecosystem conformance."/><SpecSection number="01" title="Facilitation without custody" intro="Settlement uses Stellar's authorization model: the buyer signs a narrowly scoped auth entry, the facilitator verifies it, builds the invocation, sponsors fees and submits it." items={specs}/><SpecSection dark number="02" title="Discovery makes services useful to agents" intro="The Bazaar turns isolated paid endpoints into a market agents can search. Resources remain interoperable with the broader x402 ecosystem and are indexed off-chain by default." items={discovery}/><X402Flow/><DeliverySection/><ProductCTA title="Build the open payment layer for Stellar agents."/></>}

function SpecSection({number,title,intro,items,dark=false}:{number:string;title:string;intro:string;items:string[][];dark?:boolean}){return <section className={`section ${dark?'bg-[#0b0e14]':'bg-paper text-ink'}`}><div className="shell"><div className="grid gap-10 lg:grid-cols-[.72fr_1.28fr] lg:gap-20"><div><span className="eyebrow">{number} / Specification</span><h2 className={`section-title ${dark?'':'text-ink'}`}>{title}</h2><p className={`mt-5 leading-7 ${dark?'text-cloud':'text-slate-600'}`}>{intro}</p></div><div className={`grid gap-px overflow-hidden rounded-xl border ${dark?'border-white/10 bg-white/10':'border-slate-200 bg-slate-200'} sm:grid-cols-2`}>{items.map(([name,text])=><article key={name} className={`p-6 ${dark?'bg-ink':'bg-white'}`}><h3 className="font-semibold">{name}</h3><p className={`mt-3 text-sm leading-6 ${dark?'text-cloud':'text-slate-600'}`}>{text}</p></article>)}</div></div></div></section>}

function X402Flow(){return <section className="section bg-paper text-ink"><div className="shell"><SectionHead light eyebrow="03 / Agent interface" title="Discover → pay → retry, behind structured MCP tools." text="The agent-facing server provides deterministic inputs, outputs and machine-readable error codes so runtimes do not need pre-baked service integrations or prose parsing."/><div className="mt-12 grid gap-3 md:grid-cols-4">{[['01','SEARCH','Find ranked Stellar resources'],['02','SELECT','Inspect terms and metadata'],['03','AUTHORIZE','Sign exact or upto authority'],['04','CALL','Retry and receive the resource']].map(([n,k,t])=><div key={k} className="rounded-xl border border-slate-200 bg-white p-6"><span className="font-mono text-[9px] text-blue-700">{n}</span><h3 className="mt-8 font-mono text-xs font-semibold">{k}</h3><p className="mt-2 text-sm text-slate-600">{t}</p></div>)}</div></div></section>}

function DeliverySection(){const groups=[['Settlement schemes','exact plus a Stellar upto specification and implementation contributed upstream; batch settlement and auth-capture remain phase-two work.'],['Conformance evidence','Canonical-client e2e runs, both networks, settled hashes per network and scheme, supported contract output, and non-null rejection reasons.'],['Security readiness','Threat modeling and third-party review of settlement, auth validation, replay resistance, discovery poisoning and any introduced contract.'],['Developer adoption','Seller, buyer/agent and operator guides; SDK helpers; live testnet examples; and a path from documentation to discovery in under an hour.'],['Operations','Channel-account throughput strategy, monitoring, degraded-mode behavior, runbook, 99%+ public endpoint target and maintained spec regression coverage.'],['Open ecosystem','Permissive dependencies, self-hostable deployment, upstream coordination and a documented conformance-maintenance commitment.']];return <section className="section"><div className="shell"><SectionHead eyebrow="04 / Production standard" title="Reliability is proven at the wire—not asserted in copy." text="The product is ready when standard clients, independent reviewers and other operators can verify its behavior."/><div className="mt-12 divide-y divide-white/10 border-y border-white/10">{groups.map(([h,t],i)=><div key={h} className="grid gap-3 py-6 sm:grid-cols-[50px_220px_1fr]"><span className="font-mono text-[10px] text-steel">0{i+1}</span><h3 className="font-semibold">{h}</h3><p className="text-sm leading-6 text-cloud">{t}</p></div>)}</div></div></section>}

function RuntimePage(){usePageMeta('API + Runtime SDK | Atonima','The agent-native financial execution API and SDK for semantic actions and persistent automations on Stellar.');const lifecycle=[['Resolve','Map semantic actions to verified assets, routes and protocol adapters.'],['Build','Construct contract calls, arguments, resources and transaction envelopes internally.'],['Simulate','Estimate outputs, fees and authorization through Stellar RPC before submission.'],['Authorize','Request policy-bound authority through the connected account or signer provider.'],['Submit','Sponsor and submit prepared actions with idempotency and confirmation tracking.'],['Persist','Store recurring strategies with immutable policy and approval context.'],['Evaluate','Produce reproducible EXECUTE, SKIP or STOP decisions from live state.'],['Observe','Return intent-level status while retaining inspectable transaction evidence.']];return <><ProductHero tag="Product / API + Runtime SDK" status="Architecture defined · SDK contract pending" title="Financial actions for agents—not transaction primitives." text="Applications and AI agents call Atonima over HTTPS or through an SDK. No Stellar CLI or local Stellar SDK is required for the standard integration. Atonima selects protocols, builds and simulates transactions, coordinates authorization, sponsors submission and manages execution state."/><InterfaceLayers/><section className="section bg-paper text-ink"><div className="shell"><SectionHead light eyebrow="02 / Runtime responsibilities" title="Everything below the semantic action becomes infrastructure." text="The normal interface returns actions, quotes, previews and status—not contract functions, ScVals or transaction XDR. Advanced integrators can request the underlying transaction when needed."/><div className="mt-12 grid gap-px overflow-hidden rounded-xl border border-slate-200 bg-slate-200 sm:grid-cols-2 lg:grid-cols-4">{lifecycle.map(([h,t],i)=><article className="bg-white p-6" key={h}><span className="font-mono text-[9px] text-blue-700">0{i+1}</span><h3 className="mt-8 font-semibold">{h}</h3><p className="mt-3 text-sm leading-6 text-slate-600">{t}</p></article>)}</div></div></section><SpecSection dark number="03" title="Deterministic at every boundary" intro="Identical state and compiled conditions must produce the same runtime decision. Dynamic calculation may use live data, but it remains inside approved constraints." items={[["Protocol adapters","Atonima owns contract selection, function mapping, argument encoding and network configuration for supported protocols."],["Optional XDR transparency","Prepared transaction data remains available to wallets and advanced integrators without becoming the default agent interface."],["SocketFi and other signers","SocketFi can provide smart-account authorization and policy-bound execution; Atonima determines the financial action and remains open to additional signer providers."],["Complete observability","Correlate intent, route, simulation, authorization, submission, confirmation and automation lifecycle events."]]}/><ProductCTA title="Give every application a semantic financial interface."/></>}

function InterfaceLayers(){return <section className="section"><div className="shell"><SectionHead eyebrow="01 / Integration model" title="One API. Multiple agent-native interfaces." text="HTTPS is the core platform surface. The SDK, Skills, MCP tools and an optional developer CLI compose over the same typed action schemas."/><div className="mt-12 grid gap-4 lg:grid-cols-[1fr_auto_1fr_auto_1fr] lg:items-stretch"><Layer title="Agent + application" items={['Codex and agent runtimes','Web, mobile and backends','Bots and merchant systems']}/><FlowArrow/><Layer accent title="Atonima API + SDK" items={['Semantic actions','Persistent automations','Discovery and preview']}/><FlowArrow/><Layer title="Stellar execution" items={['Protocol adapters','Simulation and XDR','Authorization and submission']}/></div><div className="mt-5 rounded-xl border border-white/10 bg-white/[.03] p-5 font-mono text-[11px] leading-6 text-cloud"><span className="text-signal">POST /v1/actions/swap</span> &nbsp;→&nbsp; discover route &nbsp;→&nbsp; preview &nbsp;→&nbsp; authorize &nbsp;→&nbsp; execute &nbsp;→&nbsp; status</div></div></section>}

function Layer({title,items,accent=false}:{title:string;items:string[];accent?:boolean}){return <div className={`rounded-xl border p-6 ${accent?'border-signal/30 bg-signal/[.06]':'border-white/10 bg-white/[.025]'}`}><h3 className="font-semibold">{title}</h3><ul className="mt-5 space-y-3">{items.map(x=><li key={x} className="flex items-center gap-2 text-sm text-cloud"><span className="size-1 rounded-full bg-signal"/>{x}</li>)}</ul></div>}
function FlowArrow(){return <div className="hidden items-center text-steel lg:flex">→</div>}

function DiscoveryPage(){usePageMeta('Discovery + Skills | Atonima','Protocol, asset and capability discovery for agents using Atonima on Stellar.');const registry=[['Protocols','Inspect supported and discovered protocols, categories, network deployments, adapter support and current status.'],['Capabilities','Understand which semantic actions—swap, deposit, borrow, quote and more—are active through each adapter.'],['Assets','Resolve issuers, Stellar Asset Contracts, decimals, supported token methods and verification context.'],['Underlying functions','Inspect relevant contract addresses and active Soroban functions without assuming responsibility for encoding or invocation.'],['Verification evidence','Use status, source, interface match, protocol version, last-checked ledger, risk level and warnings—not a single opaque boolean.'],['Action schemas','Retrieve descriptions, typed inputs, authorization requirements, preview support and policy constraints for each action.']];return <><ProductHero tag="Product / Discovery + Skills" status="Agent-native protocol intelligence" title="Abstract the transaction. Expose the evidence." text="Atonima helps agents discover what they can do on Stellar, understand supported protocols and assets, inspect verification evidence and preview execution—without teaching them to assemble contract calls."/><SpecSection number="01" title="Discoverability without execution burden" intro="An agent can inspect a protocol address, capability or underlying function for checks and balances. Atonima remains responsible for calling supported protocols correctly." items={registry}/><DiscoveryFlow/><SkillsSection/><VerificationSection/><ProductCTA title="Let agents understand before they act."/></>}

function DiscoveryFlow(){const steps=[['DISCOVER','What exists?'],['DESCRIBE','What does it do?'],['QUOTE','What will it cost or return?'],['PREVIEW','What exactly would happen?'],['VALIDATE','Is it permitted and safe?'],['EXECUTE','Perform the authorized action.'],['VERIFY','What happened on-chain?']];return <section className="section"><div className="shell"><SectionHead eyebrow="02 / Preferred agent flow" title="Reason first. Commit value last." text="Discovery and dry-run are part of the safety model, giving an autonomous system structured checkpoints before funds move."/><div className="mt-12 grid gap-3 sm:grid-cols-2 lg:grid-cols-7">{steps.map(([h,t],i)=><article key={h} className="rounded-xl border border-white/10 bg-white/[.025] p-5"><span className="font-mono text-[9px] text-steel">0{i+1}</span><h3 className="mt-7 font-mono text-[11px] text-signal">{h}</h3><p className="mt-2 text-xs leading-5 text-cloud">{t}</p></article>)}</div></div></section>}

function SkillsSection(){return <section className="section bg-paper text-ink"><div className="shell grid gap-12 lg:grid-cols-2 lg:gap-24"><div><SectionHead light eyebrow="03 / Skills" title="Teach capabilities, not contract mechanics." text="Skills explain when and why an agent should use an Atonima action. Typed API schemas define the input. Protocol adapters keep contract IDs, ScVal encoding and XDR out of the agent's normal context."/><div className="mt-8 flex flex-wrap gap-2">{['payments','tokens','swaps','aquarius','blend','dca','rebalance','distributions'].map(x=><span key={x} className="rounded-md border border-slate-200 bg-white px-3 py-2 font-mono text-[10px] text-slate-600">{x}/SKILL.md</span>)}</div></div><div className="overflow-hidden rounded-xl bg-ink"><div className="border-b border-white/10 px-5 py-3 font-mono text-[10px] text-steel">aquarius/SKILL.md</div><pre className="overflow-x-auto p-6 font-mono text-[11px] leading-6 text-cloud">{`# Aquarius Swap\n\nUse Atonima to exchange supported Stellar assets.\n\n## Action\nswap\n\n## Input\nfrom · to · amount · maxSlippageBps\n\n## Principle\nDescribe the outcome. Atonima selects and calls\nthe supported protocol adapter.`}</pre></div></div></section>}

function VerificationSection(){const states=['verified','community-verified','discovered','unverified','deprecated','blocked'];return <section className="section"><div className="shell grid gap-12 lg:grid-cols-[.8fr_1.2fr] lg:gap-24"><SectionHead eyebrow="04 / Protocol trust" title="Verification is evidence, not a badge." text="Policies can require verified adapters, acceptable risk levels, matching interfaces and recent checks before Atonima will prepare an action."/><div><div className="flex flex-wrap gap-2">{states.map((x,i)=><span key={x} className={`rounded-full border px-3 py-1.5 font-mono text-[10px] ${i===0?'border-signal/30 bg-signal/10 text-signal':'border-white/10 text-steel'}`}>{x}</span>)}</div><pre className="mt-6 overflow-x-auto rounded-xl border border-white/10 bg-black/20 p-6 font-mono text-[11px] leading-6 text-cloud">{`{\n  "status": "verified",\n  "contractMatch": true,\n  "interfaceMatch": true,\n  "protocolVersion": "3",\n  "lastCheckedLedger": 64000000,\n  "risk": { "level": "low", "warnings": [] }\n}`}</pre></div></div></section>}

function IntentsPage(){usePageMeta('Intent Infrastructure | Atonima','Standardized actions, persistent automations and higher-level financial intents with policy-bound compilation.');return <><ProductHero tag="Product / Intent Infrastructure" title="From one action to an enduring financial objective." text="Atonima separates what an agent wants to accomplish from who may authorize it and how financial infrastructure should execute it."/><IntentLevels/><SpecSection number="02" title="Strict before powerful" intro="The validator selects an action schema, normalizes canonical values and fails closed on ambiguity before policy evaluation begins." items={[["Standard schemas","Transfer, swap, deposit, withdraw, borrow, repay, disbursement and treasury formats with explicit required fields."],["Strict mode","Reject missing, malformed, unexpected and unsupported values by default."],["Sanitize mode","Optionally remove unknown non-sensitive fields while emitting an audit event."],["Canonical representation","Normalize identifiers, assets, amounts, timestamps and network values before hashing."]]}/><SpecSection dark number="03" title="Authority is a separate decision" intro="Validated structure does not imply permission. Policy binds organizational, financial, protocol and delegated authority before compilation." items={[["Policy evaluation","Allowed actions, assets, protocols, destinations, volumes, automation limits and delegation scope."],["Decision layer","Return ALLOW, DENY or REQUIRE_APPROVAL with matched rules, effective limits and reasons."],["Approval binding","Link approval to the exact intent hash and prevent material modification after authorization."],["Deterministic plans","Resolve approved intent into protocol-specific operations without inventing a new objective or widening authority."]]}/><ProductCTA title="Give agents an interface that finance can trust."/></>}

function IntentLevels(){const levels=[['01','ACTIONS','Execute once',['transfer','swap','deposit','withdraw','borrow','repay']],['02','AUTOMATIONS','Persist over time',['DCA','rebalance','distribution','recurring payment']],['03','INTENTS','Maintain an objective',['target allocation','scheduled investment','bounded API spend','approved yield']]];return <section className="section"><div className="shell"><SectionHead eyebrow="01 / Semantic model" title="A progression from calls to objectives." text="Simple actions execute once. Automations preserve an approved strategy. Higher-level intents compile financial objectives into deterministic, policy-bound plans."/><div className="mt-12 grid gap-4 lg:grid-cols-3">{levels.map(([n,h,d,items])=><article key={String(h)} className="rounded-xl border border-white/10 bg-white/[.025] p-6"><span className="font-mono text-[9px] text-steel">{String(n)}</span><h3 className="mt-8 text-xl font-semibold">{String(h)}</h3><p className="mt-2 text-sm text-signal">{String(d)}</p><div className="mt-6 flex flex-wrap gap-2">{(items as string[]).map(x=><span key={x} className="rounded border border-white/10 px-2 py-1 text-[10px] text-cloud">{x}</span>)}</div></article>)}</div></div></section>}

function ProductCTA({title}:{title:string}){return <section className="bg-signal text-ink"><div className="shell flex flex-col gap-6 py-14 lg:flex-row lg:items-center lg:justify-between"><h2 className="max-w-2xl text-3xl font-semibold tracking-tight">{title}</h2><div className="flex flex-col gap-3 sm:flex-row"><a href={github} target="_blank" rel="noreferrer" className="button button-dark"><Github className="size-4"/> GitHub</a><a href="/build" className="button button-light">Build with Atonima <ArrowRight className="size-4"/></a></div></div></section>}

function BuildPage(){usePageMeta('Build with Atonima | Developer integration','Integrate delegated financial automations on Stellar with the Atonima TypeScript SDK and production API.');const flow=[['01','PROPOSE','Define the strategy, schedule, network and bounded authority.'],['02','AUTHORIZE','Create the delegated session in the connected smart-account wallet.'],['03','PAY','Prepare, sign and settle the exact USDC service payment.'],['04','ACTIVATE','Bind the on-chain policy, choose the first run and start scheduling.'],['05','OPERATE','Read state, pause, resume, cancel and revoke with an auditable lifecycle.']];const strategies=[['Dollar-cost averaging','Execute bounded Aquarius swaps on a recurring schedule with per-run and total spend limits.',['Aquarius routing','Slippage bounds','Recipient allowlist']],['Portfolio rebalancing','Value allowed assets, compare target weights and submit at most one corrective trade per check.',['Basis-point targets','Threshold checks','Bounded trade size']],['Token disbursement','Send one-time or repeating token distributions to a fixed, policy-approved recipient set.',['1–100 recipients','Exact base units','One-time or recurring']]];return <>
  <section className="border-b border-slate-200 bg-[#f3f6fa] pt-[72px] text-ink"><div className="shell py-16 sm:py-20"><motion.div initial={{opacity:0,y:14}} animate={{opacity:1,y:0}} className="grid gap-10 lg:grid-cols-[1fr_auto] lg:items-end"><div><div className="mb-7 flex flex-wrap items-center gap-2 font-mono text-[10px] uppercase tracking-[.14em] text-slate-600"><span className="rounded bg-ink px-2.5 py-1.5 text-signal">Developer workspace</span><span>/</span><span>Atonima Core</span><span>/</span><span>SDK v0.2</span></div><h1 className="max-w-5xl text-4xl font-semibold leading-[1.02] tracking-[-.045em] sm:text-5xl lg:text-6xl">Build a financial automation.<br/><span className="text-blue-700">Keep its authority bounded.</span></h1><p className="mt-6 max-w-2xl text-lg leading-8 text-slate-600">A practical integration guide for wallets, applications and agents using delegated sessions on Stellar.</p></div><div className="flex flex-col gap-3 sm:flex-row lg:flex-col"><a href={docs} target="_blank" rel="noreferrer" className="button bg-ink text-white hover:bg-slate-800">Technical documentation <ExternalLink className="size-4"/></a><a href={sdkPackage} target="_blank" rel="noreferrer" className="inline-flex min-h-12 items-center justify-between gap-8 rounded-lg border border-slate-300 bg-white px-5 font-mono text-xs font-semibold text-ink transition hover:border-blue-600"><span>pnpm add @atonima/sdk</span><ExternalLink className="size-3.5 text-blue-700"/></a></div></motion.div><div className="mt-12 grid overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm md:grid-cols-[1fr_1fr_1fr_auto]"><div className="border-b border-slate-200 p-5 md:border-b-0 md:border-r"><span className="block font-mono text-[9px] uppercase tracking-wider text-slate-600">Runtime</span><b className="mt-2 block text-sm">Browser or Node.js 18+</b></div><div className="border-b border-slate-200 p-5 md:border-b-0 md:border-r"><span className="block font-mono text-[9px] uppercase tracking-wider text-slate-600">Networks</span><b className="mt-2 block text-sm">Stellar testnet + public</b></div><div className="border-b border-slate-200 p-5 md:border-b-0 md:border-r"><span className="block font-mono text-[9px] uppercase tracking-wider text-slate-600">Strategies</span><b className="mt-2 block text-sm">DCA · Rebalance · Disburse</b></div><a href={`${github}/atonima-core`} target="_blank" rel="noreferrer" className="flex items-center justify-center gap-2 bg-slate-50 px-6 py-5 text-sm font-semibold hover:bg-slate-100"><Github className="size-4"/> Source</a></div></div></section>
  <section className="section bg-paper text-ink"><div className="shell"><SectionHead light eyebrow="01 / Integration lifecycle" title="From proposal to scheduled execution." text="The API owns automation state and telemetry. Your wallet owns creation and revocation of the delegated on-chain session, keeping authority visible at the correct boundary."/><div className="mt-14 grid gap-px overflow-hidden rounded-2xl border border-slate-200 bg-slate-200 md:grid-cols-5">{flow.map(([n,h,t])=><article key={h} className="bg-white p-6"><span className="font-mono text-[9px] text-blue-700">{n}</span><h3 className="mt-8 font-mono text-xs font-semibold">{h}</h3><p className="mt-3 text-sm leading-6 text-slate-600">{t}</p></article>)}</div><div className="mt-6 flex items-start gap-3 rounded-xl border border-blue-100 bg-blue-50 p-5 text-sm leading-6 text-slate-700"><ShieldCheck className="mt-0.5 size-5 shrink-0 text-blue-700"/><p><b className="text-ink">Two systems, one explicit contract.</b> Atonima is authoritative for proposal, payment, scheduling, run counts and lifecycle. The integrating wallet remains authoritative for delegated session authorization.</p></div></div></section>
  <section className="section"><div className="shell"><SectionHead eyebrow="02 / Strategy implementations" title="Three policies. Three concrete proposal shapes." text="These TypeScript examples follow the production SDK contract: base-unit amount strings, finite run limits, ledger bounds and strategy-specific authorization constraints."/><div className="mt-12 grid gap-4 lg:grid-cols-3">{strategies.map(([name,text,tags])=><article key={name as string} className="rounded-xl border border-white/10 bg-white/[.025] p-5"><h3 className="font-semibold">{name as string}</h3><p className="mt-2 text-sm leading-6 text-cloud">{text as string}</p><div className="mt-4 flex flex-wrap gap-2">{(tags as string[]).map(tag=><span key={tag} className="rounded border border-white/10 px-2 py-1 font-mono text-[9px] text-steel">{tag}</span>)}</div></article>)}</div><StrategyExamples/></div></section>
  <section className="section bg-paper text-ink"><div className="shell grid gap-12 lg:grid-cols-[.8fr_1.2fr] lg:gap-24"><div><SectionHead light eyebrow="03 / Operational model" title="Designed for the full lifecycle—not only the happy path." text="Production integrations can inspect derived state and remaining runs, recover idempotently, and separate reversible scheduling controls from cryptographic revocation."/><a href={docs} target="_blank" rel="noreferrer" className="mt-8 inline-flex items-center gap-2 text-sm font-semibold text-blue-700">Explore API and SDK references <ExternalLink className="size-4"/></a></div><div className="grid gap-px overflow-hidden rounded-xl border border-slate-200 bg-slate-200 sm:grid-cols-2">{[['Inspectable state','PROPOSED, PAYMENT_REQUIRED, READY_TO_ACTIVATE, ACTIVE, PAUSED and terminal outcomes.'],['Safe retries','Payment settlement and activation are idempotent; scheduled runs use deterministic keys.'],['Explicit controls','Pause and resume scheduling, cancel API execution, and revoke authority on-chain when required.'],['Operational evidence','Track next and last runs, spend totals, transaction hashes, failures and payment status.']].map(([h,t])=><article key={h} className="bg-white p-6"><h3 className="font-semibold">{h}</h3><p className="mt-3 text-sm leading-6 text-slate-600">{t}</p></article>)}</div></div></section>
  <section className="bg-signal text-ink"><div className="shell grid gap-8 py-16 lg:grid-cols-[1fr_auto] lg:items-center"><div><span className="mb-3 block font-mono text-[10px] font-bold uppercase tracking-[.18em]">Ready to integrate?</span><h2 className="max-w-3xl text-3xl font-semibold tracking-tight sm:text-4xl">Take the SDK path—or design the right boundary with us.</h2></div><div className="flex flex-col gap-3 sm:flex-row"><a href={docs} target="_blank" rel="noreferrer" className="button button-dark"><BookOpen className="size-4"/> Open documentation</a><a href="mailto:hello@atonima.com?subject=Build%20with%20Atonima" className="button button-light">Talk to the team <ArrowRight className="size-4"/></a></div></div></section>
  </>}

function StrategyExamples(){const [active,setActive]=useState<'DCA'|'REBALANCE'|'DISBURSEMENT'>('DCA');const [copied,setCopied]=useState(false);const shared=`import { Atonima } from "@atonima/sdk";

Atonima.configure({ environment: "PRODUCTION" });

const currentLedger = 64_000_000; // Read from Stellar RPC
const common = {
  network: "PUBLIC" as const,
  walletAddress: "C_YOUR_SMART_ACCOUNT",
  validAfterLedger: currentLedger + 5,
  expiresAtLedger: currentLedger + 17_280,
};`;
const examples={DCA:`${shared}

const proposal = await Atonima.propose({
  ...common,
  type: "DCA",
  maxUses: 12,
  schedule: { kind: "INTERVAL", expression: "1 week", timezone: "UTC" },
  strategy: {
    protocol: {
      name: "AQUARIUS",
      contractId: "C_AQUARIUS_ROUTER",
      functionName: "swap_chained",
    },
    inputAsset: "C_USDC_TOKEN",
    outputAsset: "C_XLM_TOKEN",
    amountPerRun: "250000000", // 25 USDC at 7 decimals
    maxTotalAmount: "3000000000",
    slippageBps: 100,
    spendRecipients: ["C_AQUARIUS_ROUTER"],
  },
});`,REBALANCE:`${shared}

const proposal = await Atonima.propose({
  ...common,
  type: "REBALANCE",
  maxUses: 24,
  schedule: { kind: "INTERVAL", expression: "1 day", timezone: "UTC" },
  strategy: {
    protocol: {
      name: "AQUARIUS",
      contractId: "C_AQUARIUS_ROUTER",
      functionName: "swap_chained",
    },
    allowedAssets: ["C_USDC_TOKEN", "C_XLM_TOKEN"],
    targetWeightsBps: [6000, 4000], // Must total 10,000
    rebalanceThresholdBps: 500,
    slippageBps: 100,
    maxTradeAmount: "1000000000",
    maxTotalAmount: "24000000000",
    spendRecipients: ["C_AQUARIUS_ROUTER"],
  },
});`,DISBURSEMENT:`${shared}

const proposal = await Atonima.propose({
  ...common,
  type: "DISBURSEMENT",
  maxUses: 1,
  // A one-time run still uses an interval schedule; maxUses makes it run once.
  schedule: { kind: "INTERVAL", expression: "1 year", timezone: "UTC" },
  strategy: {
    asset: "C_USDC_TOKEN",
    repeat: false,
    recipients: [
      { address: "G_FIRST_RECIPIENT", amount: "250000000" },
      { address: "C_SECOND_RECIPIENT", amount: "100000000" },
    ],
  },
});`};const code=examples[active];return <div className="mt-8 overflow-hidden rounded-2xl border border-white/10 bg-[#080b10]"><div className="flex flex-col justify-between gap-3 border-b border-white/10 p-3 sm:flex-row sm:items-center"><div className="flex overflow-x-auto" aria-label="Strategy example">{(['DCA','REBALANCE','DISBURSEMENT'] as const).map(item=><button key={item} aria-pressed={active===item} onClick={()=>setActive(item)} className={`rounded-lg px-4 py-2.5 font-mono text-[10px] font-semibold transition ${active===item?'bg-signal text-ink':'text-steel hover:bg-white/[.05] hover:text-white'}`}>{item}</button>)}</div><button aria-live="polite" onClick={()=>{navigator.clipboard?.writeText(code);setCopied(true);setTimeout(()=>setCopied(false),1500)}} className="flex items-center justify-center gap-2 rounded-lg border border-white/10 px-4 py-2.5 font-mono text-[10px] text-cloud hover:text-white"><Copy className="size-3"/>{copied?'Copied':'Copy example'}</button></div><div className="grid lg:grid-cols-[1fr_250px]"><pre className="max-h-[680px] overflow-auto p-6 font-mono text-[11px] leading-6 text-[#c5cfdd] sm:p-8"><code>{code}</code></pre><aside className="border-t border-white/10 bg-white/[.025] p-6 lg:border-l lg:border-t-0"><span className="font-mono text-[9px] uppercase tracking-wider text-signal">Implementation notes</span><ul className="mt-5 space-y-4 text-xs leading-5 text-cloud">{active==='DCA'?<><li>Per-run and lifetime limits are bound into the session policy.</li><li>The router and <code>swap_chained</code> function must match the selected network.</li></>:active==='REBALANCE'?<><li>Weights use basis points and must total exactly 10,000.</li><li>An in-threshold check is skipped without consuming a session use.</li></>:<><li>Amounts are token base-unit strings—never floating-point decimals.</li><li>Recipients are fixed when the delegated policy is created.</li></>}</ul><a href={docs} target="_blank" rel="noreferrer" className="mt-7 inline-flex items-center gap-1 text-xs font-semibold text-signal">Full API reference <ExternalLink className="size-3"/></a></aside></div></div>}

function NotFound(){usePageMeta('Page not found | Atonima','The requested Atonima page could not be found.');return <section className="hero-grid flex min-h-[calc(100vh-200px)] items-center pt-[72px]"><div className="shell py-24"><span className="font-mono text-sm text-signal">ERROR / 404</span><h1 className="mt-6 max-w-3xl text-5xl font-semibold tracking-[-.05em] sm:text-7xl">This route has no execution plan.</h1><p className="mt-6 max-w-xl text-lg leading-8 text-cloud">The requested page does not exist or has moved. No action was taken.</p><div className="mt-9 flex flex-col gap-3 sm:flex-row"><a href="/" className="button"><ArrowLeft className="size-4"/> Return home</a><a href="/x402" className="button button-ghost">Explore x402</a></div></div></section>}

function Hero() { return <section id="top" className="hero-grid relative overflow-hidden pt-[72px]">
  <div className="shell relative grid min-h-[780px] items-center gap-16 py-24 lg:grid-cols-[1.05fr_.95fr] lg:py-28">
    <motion.div initial={{opacity:0,y:24}} animate={{opacity:1,y:0}} transition={{duration:.65}}>
      <div className="status-pill"><span className="pulse"/> Built Stellar-first · designed for financial AI</div>
      <h1 className="hero-title mt-7">The control layer between <span>AI intent</span> and financial execution.</h1>
      <p className="mt-7 max-w-xl text-lg leading-8 text-cloud">Agents and applications call simple financial actions over HTTPS or through an SDK. Atonima discovers routes, validates authority, builds and simulates transactions, sponsors submission and audits every outcome.</p>
      <div className="mt-9 flex flex-col gap-3 sm:flex-row"><a href="#architecture" className="button">Explore the architecture <ArrowRight className="size-4"/></a><a href="/x402" className="button button-ghost">Explore x402</a></div>
      <p className="mt-6 flex items-center gap-2 text-xs text-steel"><Check className="size-3.5 text-signal"/> Agents express intent. Atonima controls execution authority.</p>
    </motion.div>
    <motion.div initial={{opacity:0,x:25}} animate={{opacity:1,x:0}} transition={{duration:.7,delay:.12}} className="terminal-wrap">
      <div className="terminal-bar"><div className="flex gap-1.5"><i/><i/><i/></div><span>atonima / intent pipeline</span><span className="text-signal">● operational model</span></div>
      <div className="p-5 sm:p-7"><div className="code-label">INCOMING_INTENT</div><pre className="code-block">{`{\n  "action": "transfer",\n  "asset": "USDC",\n  "amount": "400",\n  "recipient": "GABC…7QX"\n}`}</pre>
      <div className="my-5 h-px bg-white/8"/>
      <div className="space-y-3">{[['01','SCHEMA','VALID'],['02','POLICY','REQUIRE_APPROVAL'],['03','AUTHORITY','PENDING']].map(([n,k,v],i)=><div className="terminal-row" key={k}><span>{n}</span><b>{k}</b><em className={i===0?'ok':'pending'}>{v}</em></div>)}</div>
      <div className="mt-6 rounded-lg border border-amber-400/20 bg-amber-400/[.06] p-4 font-mono text-[11px] leading-6 text-amber-200"><span className="text-amber-400">// EXECUTION PAUSED</span><br/>Amount exceeds autonomous threshold.<br/>No transaction has been constructed.</div></div>
    </motion.div>
  </div>
</section>; }

function TrustStrip(){return <div className="border-y border-white/8 bg-white/[.02]"><div className="shell grid sm:grid-cols-3">{credibility.map((item,i)=><div key={item.label} className={`flex items-center gap-3 py-5 ${i ? 'sm:border-l sm:border-white/8 sm:pl-8' : ''}`}><item.icon className="size-4 text-signal"/><div><span className="block text-[11px] text-steel">{item.label}</span><b className="text-sm font-medium">{item.value}</b></div></div>)}</div></div>}

function SectionHead({eyebrow,title,text,light=false}:{eyebrow:string,title:string,text?:string;light?:boolean}){return <motion.header {...reveal} className="max-w-3xl"><span className="eyebrow">{eyebrow}</span><h2 className={`section-title ${light?'text-ink':'text-white'}`}>{title}</h2>{text&&<p className={`mt-5 max-w-2xl text-base leading-7 ${light?'text-slate-600':'text-cloud'}`}>{text}</p>}</motion.header>}

function Platform(){return <section id="platform" className="section bg-paper text-ink"><div className="shell"><div className="grid gap-12 lg:grid-cols-[.8fr_1.2fr] lg:gap-24"><SectionHead light eyebrow="01 / The platform" title="Infrastructure for controlled financial autonomy." text="Financial applications need more than agent identity. They need a reliable boundary where every proposed action can be checked before execution authority is granted."/><div className="grid gap-px overflow-hidden rounded-2xl border border-slate-200 bg-slate-200 sm:grid-cols-2">{controls.map((c,i)=><motion.article {...reveal} transition={{delay:i*.06}} key={c.title} className="bg-white p-7"><div className="mb-8 grid size-10 place-items-center rounded-lg bg-ink text-signal"><c.icon className="size-5"/></div><h3 className="font-semibold">{c.title}</h3><p className="mt-2 text-sm leading-6 text-slate-600">{c.text}</p></motion.article>)}</div></div>
  <div className="mt-20 rounded-2xl border border-slate-200 bg-white p-6 sm:p-8"><div className="flex flex-col gap-5 lg:flex-row lg:items-center lg:justify-between"><div className="max-w-xl"><span className="eyebrow mb-2">Execution boundary</span><h3 className="text-xl font-semibold">Atonima coordinates execution across the financial stack.</h3><p className="mt-2 text-sm leading-6 text-slate-600">It can compile, simulate, sponsor, submit and monitor approved actions while connected networks and financial rails perform settlement.</p></div><div className="flex max-w-xl flex-wrap gap-2">{executionBoundaries.map(x=><span key={x} className="rounded-full border border-slate-200 px-3 py-1.5 text-xs text-slate-500">{x}</span>)}</div></div></div>
  </div></section>}

function Architecture(){return <section id="architecture" className="section"><div className="shell"><SectionHead eyebrow="02 / Architecture" title="One enforceable path from request to outcome." text="Each layer answers one question, produces a structured output and leaves evidence for the next. Settlement remains with the underlying financial infrastructure."/>
  <div className="mt-14 grid gap-3 md:grid-cols-2 lg:grid-cols-3">{pipeline.map((p,i)=><motion.article {...reveal} transition={{delay:i*.05}} key={p.name} className="module-card group"><div className="flex items-start justify-between"><span className="module-number">0{i+1}</span><p.icon className="size-5 text-steel transition group-hover:text-signal"/></div><h3 className="mt-10 text-xl font-semibold">{p.name}</h3><p className="mt-2 text-sm font-medium text-signal">{p.question}</p><p className="mt-4 text-sm leading-6 text-cloud">{p.detail}</p></motion.article>)}</div>
  <div className="mt-8 flex flex-wrap items-center gap-x-4 gap-y-2 rounded-xl border border-white/10 bg-white/[.03] p-4 font-mono text-[10px] text-steel"><b className="text-white">RUNTIME STATES</b>{runtimeStates.map((x,i)=><span key={x} className="flex items-center gap-4">{i>0&&<i className="size-1 rounded-full bg-white/20"/>}{x}</span>)}</div>
  </div></section>}

function IntentDemo(){const [copied,setCopied]=useState(false); const snippet=`const result = await atonima.swap({\n  from: "USDC",\n  to: "XLM",\n  amount: "100",\n  maxSlippageBps: 50\n});`;
return <section id="developers" className="section bg-paper text-ink"><div className="shell grid items-center gap-12 lg:grid-cols-2 lg:gap-24"><motion.div {...reveal}><span className="eyebrow">03 / API + SDK</span><h2 className="section-title text-ink">Describe the outcome.<br/>Atonima handles the transaction.</h2><p className="mt-5 max-w-lg leading-7 text-slate-600">Agents call semantic financial actions through HTTPS or the SDK—not raw contract invocations. Atonima discovers the route, builds and simulates the transaction, coordinates authorization and returns intent-level status.</p><div className="mt-8 flex flex-wrap gap-2">{intentTypes.map(x=><span key={x} className="rounded-md bg-slate-100 px-3 py-2 font-mono text-[10px] text-slate-600">{x}</span>)}</div><a href="/runtime" className="mt-7 inline-flex items-center gap-2 text-sm font-semibold text-blue-700">Explore API + Runtime SDK <ArrowRight className="size-4"/></a></motion.div>
  <motion.div {...reveal} className="overflow-hidden rounded-2xl bg-[#0a0d13] shadow-2xl shadow-slate-900/15"><div className="flex items-center justify-between border-b border-white/10 px-5 py-3 font-mono text-[10px] text-steel"><span>intent.ts</span><button onClick={()=>{navigator.clipboard?.writeText(snippet);setCopied(true);setTimeout(()=>setCopied(false),1500)}} className="flex items-center gap-2 hover:text-white" aria-label="Copy code">{copied?<Check className="size-3"/>:<Copy className="size-3"/>}{copied?'Copied':'Copy'}</button></div><pre className="overflow-x-auto p-6 text-[12px] leading-7 text-[#c6d0df] sm:p-8"><code>{snippet}</code></pre><div className="border-t border-white/10 bg-white/[.03] px-6 py-4 font-mono text-[10px] text-signal">→ decision: REQUIRE_APPROVAL</div></motion.div>
  </div></section>}

function DiscoveryPreview(){return <section className="section"><div className="shell grid items-center gap-12 lg:grid-cols-[.85fr_1.15fr] lg:gap-24"><div><SectionHead eyebrow="04 / Discovery + Skills" title="Agents can inspect what Atonima abstracts." text="Discover supported protocols, assets, actions, verification evidence and underlying functions. Skills teach agents when to use a capability; Atonima remains responsible for executing it correctly."/><a href="/discovery" className="button button-ghost mt-8">Explore protocol discovery <ArrowRight className="size-4"/></a></div><div className="overflow-hidden rounded-xl border border-white/10 bg-black/20"><div className="border-b border-white/10 px-5 py-3 font-mono text-[10px] text-steel">GET /v1/discover/protocols/aquarius</div><pre className="overflow-x-auto p-6 font-mono text-[11px] leading-6 text-cloud">{`{\n  "id": "aquarius",\n  "category": "dex",\n  "verification": {\n    "status": "verified",\n    "contractMatch": true,\n    "interfaceMatch": true\n  },\n  "actions": ["swap", "quote"],\n  "atonimaSupport": { "supported": true }\n}`}</pre></div></div></section>}

function X402(){return <section id="x402" className="section x402-grid"><div className="shell"><div className="grid gap-10 lg:grid-cols-[1fr_.8fr] lg:items-end"><SectionHead eyebrow="05 / x402" title="Payments and discovery for agent commerce." text="Atonima extends its control model to x402 with non-custodial payment facilitation, service discovery and bounded agent spending on Stellar."/><motion.div {...reveal} className="lg:text-right"><span className="inline-flex rounded-full border border-signal/30 bg-signal/10 px-3 py-1.5 font-mono text-[10px] uppercase tracking-wider text-signal">x402 on Stellar</span><p className="mt-3 text-xs leading-5 text-steel">Open infrastructure for services that agents<br className="hidden lg:block"/> can discover, authorize and pay for.</p></motion.div></div>
  <div className="mt-14 grid gap-4 md:grid-cols-2 lg:grid-cols-3">{x402Tracks.map((x,i)=><motion.article {...reveal} transition={{delay:i*.05}} key={x.title} className="x402-card"><div className="flex items-center justify-between"><span className="font-mono text-xs text-steel">TRACK / {x.id}</span><x.icon className="size-5 text-signal"/></div><h3 className="mt-9 text-xl font-semibold">{x.title}</h3><p className="mt-3 min-h-[72px] text-sm leading-6 text-cloud">{x.text}</p><div className="mt-7 flex flex-wrap gap-2">{x.tags.map(t=><span key={t}>{t}</span>)}</div></motion.article>)}</div>
  </div></section>}

function Principles(){return <section className="section border-y border-white/8"><div className="shell"><div className="grid gap-12 lg:grid-cols-[.7fr_1.3fr] lg:gap-24"><SectionHead eyebrow="06 / Delivery principles" title="Credibility lives in the details." text="Financial infrastructure earns trust through precise boundaries, verifiable behavior and an operating model others can inspect."/><div className="divide-y divide-white/10">{principles.map((p,i)=><motion.article {...reveal} transition={{delay:i*.05}} key={p.title} className="grid grid-cols-[auto_1fr] gap-5 py-6 first:pt-0"><div className="grid size-10 place-items-center rounded-lg border border-white/10"><p.icon className="size-4 text-signal"/></div><div><h3 className="font-semibold">{p.title}</h3><p className="mt-2 text-sm leading-6 text-cloud">{p.text}</p></div></motion.article>)}</div></div></div></section>}

function Audience(){return <section className="section bg-paper text-ink"><div className="shell"><SectionHead light eyebrow="07 / Built for the ecosystem" title="One control surface. Many financial workflows." text="Atonima is designed to sit behind the products teams already use and in front of the infrastructure that ultimately executes value."/><div className="mt-14 grid gap-px overflow-hidden rounded-2xl border border-slate-200 bg-slate-200 sm:grid-cols-2 lg:grid-cols-3">{users.map((u,i)=><motion.article {...reveal} transition={{delay:i*.04}} key={u.title} className="bg-white p-7"><u.icon className="size-5 text-blue-700"/><h3 className="mt-8 font-semibold">{u.title}</h3><p className="mt-2 text-sm leading-6 text-slate-600">{u.text}</p></motion.article>)}</div></div></section>}

function Vision(){return <section className="section"><div className="shell grid gap-12 lg:grid-cols-2 lg:gap-24"><SectionHead eyebrow="08 / Audit and observability" title="Every decision leaves a trail." text="Correlated events connect the original request to policy, approval, compilation and eventual settlement—so teams can reconstruct what happened and why."/><motion.div {...reveal} className="overflow-hidden rounded-xl border border-white/10 bg-black/20"><div className="flex justify-between border-b border-white/10 px-5 py-3 font-mono text-[10px] text-steel"><span>LIVE EVENT STREAM</span><span>correlation: int_4p8k</span></div><div className="divide-y divide-white/[.06]">{auditEvents.map(([time,event,detail,tone])=><div className="grid grid-cols-[76px_1fr] gap-3 px-5 py-3 font-mono text-[10px] sm:grid-cols-[80px_1fr_1.2fr]" key={event}><span className="text-steel">{time}</span><span className={tone==='good'?'text-signal':tone==='warn'?'text-amber-300':'text-white'}>{event}</span><span className="col-start-2 text-steel sm:col-start-auto">{detail}</span></div>)}</div></motion.div></div></section>}

function CTA(){return <section id="contact" className="bg-signal text-ink"><div className="shell grid gap-8 py-16 lg:grid-cols-[1fr_auto] lg:items-center"><div><span className="mb-3 block font-mono text-[10px] font-bold uppercase tracking-[.18em]">Build controlled financial autonomy</span><h2 className="max-w-3xl text-3xl font-semibold tracking-tight sm:text-4xl">If your agents can move value, their authority should be explicit.</h2></div><div className="flex flex-col gap-3 sm:flex-row"><a href={github} target="_blank" rel="noreferrer" className="button button-dark"><Github className="size-4"/> Explore the repository</a><a href="mailto:hello@atonima.com?subject=Build%20with%20Atonima" className="button button-light">Start a conversation <ArrowRight className="size-4"/></a></div></div></section>}

function Footer(){return <footer className="border-t border-white/8 bg-[#07090d]"><div className="shell py-12"><div className="grid gap-10 sm:grid-cols-2 lg:grid-cols-[1.5fr_1fr_1fr]"><div><div className="flex items-center gap-3"><Mark/><b>atonima</b></div><p className="mt-4 max-w-sm text-sm leading-6 text-steel">Verification and control infrastructure for agent-generated financial actions.</p></div><div><b className="footer-head">Platform</b><div className="mt-4 space-y-3">{nav.slice(0,3).map(([l,h])=><a className="footer-link" href={h} key={l}>{l}</a>)}<a className="footer-link" href="/build">Build with Atonima</a></div></div><div><b className="footer-head">Connect</b><div className="mt-4 space-y-3"><a className="footer-link" href={docs} target="_blank" rel="noreferrer">Documentation <ChevronRight className="size-3"/></a><a className="footer-link" href={sdkPackage} target="_blank" rel="noreferrer">SDK on npm <ChevronRight className="size-3"/></a><a className="footer-link" href={github} target="_blank" rel="noreferrer">GitHub <ChevronRight className="size-3"/></a><a className="footer-link" href="mailto:hello@atonima.com">Contact <ChevronRight className="size-3"/></a></div></div></div><div className="mt-12 flex flex-col gap-3 border-t border-white/8 pt-6 text-[11px] text-steel sm:flex-row sm:justify-between"><p>© 2026 Atonima Labs. All rights reserved.</p><p>Stellar-first · Infrastructure-agnostic by design</p></div></div></footer>}
